do $$
declare n integer; batch integer;
begin
  select count(*) into batch from _new;
  if batch <> 118 then
    raise exception 'Expected 118 TX rows staged, found %.', batch;
  end if;

  -- 1. Coordinates required for every inserted row, in the U.S. envelope.
  select count(*) into n from _new
   where lat is null or lng is null or lat = 0 or lng = 0
      or lat not between 24.0 and 49.5 or lng not between -125.0 and -66.5;
  if n <> 0 then raise exception '% row(s) have an unusable coordinate.', n; end if;

  -- 2. COORDINATE-COLLISION GUARD, NOT WEAKENED. No duplicate coordinate in
  --    the batch. The export itself has zero duplicate coordinates, so any hit
  --    here is a generation fault.
  select count(*) into n from (select lat, lng from _new group by lat, lng having count(*) > 1) d;
  if n <> 0 then raise exception '% coordinate(s) shared by more than one site.', n; end if;

  -- 3. detail_slug unique in the batch and free in the table.
  select count(*) into n from (select detail_slug from _new group by detail_slug having count(*) > 1) d;
  if n <> 0 then raise exception '% duplicate detail_slug(s) inside the batch.', n; end if;
  select count(*) into n from _new x join public.locations l on l.detail_slug = x.detail_slug;
  if n <> 0 then raise exception '% detail_slug(s) already exist in locations.', n; end if;

  -- 4. Store number must not already be present for this state. Third-party
  --    brands carry their own numbering and are excluded from the check.
  select count(*) into n
    from _new x join public.locations l
      on l.state = x.state and substring(l.name from '#\s*(\d+)') = x.source_ref
   where l.deleted_at is null
     and l.name !~* '^(southern tire mart|speedway|blue beacon|pro stop)'
     and l.name !~* '\(CAT #[0-9]+\)';
  if n <> 0 then raise exception '% store number(s) already exist in TX.', n; end if;

  -- 5. Proximity: refuse to drop a pin within ~150 m of a published location.
  select count(*) into n
    from _new x join public.locations l
      on l.deleted_at is null and l.is_published and l.lat is not null
     and abs(l.lat - x.lat) < 0.0015 and abs(l.lng - x.lng) < 0.0015;
  if n <> 0 then raise exception '% row(s) sit within ~150 m of a published location.', n; end if;

  -- 6. Insert. UNPUBLISHED, UNFEATURED. is_indexable and overnight_parking are
  --    NOT NAMED, so both keep their NOT NULL DEFAULT false. parking_spaces
  --    carries the operator's own count, including a stated 0.
  insert into public.locations
    (type, category_slug, name, address, city, state, zip, lat, lng,
     interstate, exit_number, parking_spaces,
     slug, detail_slug, source, is_published, is_featured)
  select 'truck_stop', 'truck-stops', x.name, x.address, x.city, x.state, x.zip, x.lat, x.lng,
         x.interstate, x.exit_number, x.parking_spaces,
         x.detail_slug, x.detail_slug, 'pilot-master-2026-07-27', false, false
    from _new x;
  get diagnostics n = row_count;
  if n <> 118 then
    raise exception 'Expected to insert exactly 118 row(s), inserted %.', n;
  end if;

  -- 7. Nothing may be published, featured or indexable by this statement.
  select count(*) into n from public.locations
   where source = 'pilot-master-2026-07-27' and state = 'TX'
     and (is_published or is_featured or is_indexable);
  if n <> 0 then raise exception 'Post-check failed: % row(s) are published/featured/indexable.', n; end if;

  -- 8. No row may claim overnight parking. The export does not state it.
  select count(*) into n from public.locations
   where source = 'pilot-master-2026-07-27' and state = 'TX' and overnight_parking;
  if n <> 0 then raise exception 'Post-check failed: % row(s) claim overnight parking.', n; end if;
end $$;

commit;

